// AI Quest service worker: caches every app and content file for offline use.
// The asset list and CACHE_VERSION live in sw-assets.js (regenerated by tools/build.mjs).
// Slide images go in a separate cache ("ai-quest-slides") that survives app updates.
importScripts("./sw-assets.js");
const CACHE = "ai-quest-" + self.CACHE_VERSION;
const SLIDES = "ai-quest-slides";
self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(self.ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => {
  e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k.startsWith("ai-quest-") && k !== CACHE && k !== SLIDES).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  const isSlide = url.pathname.includes("/slides/");
  e.respondWith(
    caches.match(e.request, { ignoreSearch: true }).then((hit) => hit || fetch(e.request).then((res) => {
      if (res.ok && url.origin === location.origin) { const copy = res.clone(); caches.open(isSlide ? SLIDES : CACHE).then((c) => c.put(e.request, copy)); }
      return res;
    }).catch(() => (isSlide ? new Response("", { status: 504 }) : caches.match("./index.html"))))
  );
});
